				"location": "body",
				"path": [
					"tipo"
				],
				"displayName": "Tipo",
				"required": false,
				"type": "options",
				"options": [
					{
						"name": "NEUROMUSCULAR",
						"value": "NEUROMUSCULAR"
					},
					{
						"name": "CARDIOVASCULAR",
						"value": "CARDIOVASCULAR"
					}
				],
				"description": "Tipo da atividade física. Valores disponíveis - NEUROMUSCULAR (Neuromuscular) - CARDIOVASCULAR (Cardiovascular)",
				"defaultValue": "NEUROMUSCULAR"
