		"method": "POST",
		"path": "/avaliacao/salvarRespostasParQ",
		"operationId": "salvarRespostasParQUsingPOSTtreinoApi",
		"description": "Salva as respostas do questionário PAR-Q (Physical Activity Readiness Questionnaire) fornecidas por um aluno, incluindo validação das respostas e determinação se o PAR-Q é positivo ou negativo. O sistema processa as respostas, salva a assinatura digital se fornecida e atualiza o status do cliente.",
		"parameters": [
			{
				"name": "empresaId",
				"in": "header",
				"required": true,
				"type": "string",
				"description": "Código da empresa"
			},
			{
				"name": "usuarioZw",
				"in": "query",
				"required": true,
				"type": "string",
				"description": "Código identificador do usuário responsável pelo salvamento das respostas PAR-Q"
			},
			{
				"name": "app",
				"in": "query",
				"required": false,
				"type": "boolean",
				"description": "Indica se a requisição está sendo feita pelo aplicativo. Quando true, o usuário não é obrigatório e será salvo como nulo."
			},
			{
				"name": "pactoFlow",
				"in": "query",
				"required": false,
				"type": "boolean",
				"description": "Indica se a requisição está sendo feita pelo Pacto Flow. Quando true, o PAR-Q não será salvo com o tipo DF."
			},
			{
				"name": "User-Agent",
				"in": "header",
				"required": false,
				"type": "string",
				"description": "User-Agent"
			}
		],
