		"path": "/psec/configuracoes/processos/excluirCliNaoExisteZwLote",
		"operationId": "pcrExcluirCliNaoExisteZwLoteUsingPOSTtreinoApi",
		"description": "Versão otimizada (set-based, em lotes transacionais) do processo de manutenção que exclui registros que não existem mais no sistema ZW. Indicada para grandes volumes. ATENÇÃO: este processo SÓ é suportado em bancos PostgreSQL 18 ou superior. Antes de chamar, valide no banco em produção a versão do banco deste cliente; por isso o parâmetro de confirmação 'estouCienteQueEstaChaveUtilizaPostgreSQL18' é obrigatório e deve vir como true. Se vier false, a operação é cancelada sem qualquer alteração. (O serviço ainda revalida a versão do banco internamente.) Exposto via POST (e não GET) por ser uma operação destrutiva: evita disparo acidental/CSRF por link/img/prefetch, que só ocorrem com métodos GET.",
		"parameters": [
			{
				"name": "empresaId",
				"in": "header",
				"required": true,
				"type": "string",
				"description": "Código da empresa"
			},
			{
				"name": "qtExcluir",
				"in": "query",
				"required": true,
				"type": "integer",
				"description": "Quantidade MÁXIMA de clientesintetico a excluir nesta chamada. OBRIGATÓRIO. O processo varre toda a base do Treino, apura os órfãos (codigocliente que não existe mais como cliente.codigo no ZW) e exclui no máximo esta quantidade. Permite fatiar a limpeza de grandes volumes (~400 mil) em várias chamadas, ajustando o tamanho conforme a carga do servidor."
			},
			{
				"name": "estouCienteQueEstaChaveUtilizaPostgreSQL18",
				"in": "query",
				"required": true,
				"type": "boolean",
				"description": "Confirmação OBRIGATÓRIA de que a chave/cliente usa PostgreSQL 18. Deve ser true para prosseguir; com false a operação é cancelada."
			},
			{
				"name": "tamanhoLote",
				"in": "query",
				"required": false,
				"type": "integer",
				"description": "Quantidade de clientes por transação (lote/commit). Se não informado, usa o padrão 10000. Diferente de qtExcluir, que limita o TOTAL da chamada."
			},
			{
				"name": "confirmoExclusaoTotalClientesDaEmpresa",
				"in": "query",
				"required": false,
				"type": "boolean",
				"description": "Confirmação de segurança contra exclusão em massa acidental. Só é exigida quando os clientes a excluir passam de 50% da base do Treino (ex.: leitura do ZW vazia/anômala). Nesse caso, deve ser true para prosseguir."
			}
		],
		"inputFields": [
			{
				"id": "header__empresaId",
				"location": "header",
				"path": [
					"empresaId"
				],
				"displayName": "Empresa ID",
				"required": true,
				"type": "string",
				"description": "Código da empresa"
			},
			{
				"id": "query__qtExcluir",
				"location": "query",
				"path": [
					"qtExcluir"
				],
				"displayName": "Qt Excluir",
				"required": true,
				"type": "string",
				"description": "Quantidade MÁXIMA de clientesintetico a excluir nesta chamada. OBRIGATÓRIO. O processo varre toda a base do Treino, apura os órfãos (codigocliente que não existe mais como cliente.codigo no ZW) e exclui no máximo esta quantidade. Permite fatiar a limpeza de grandes volumes (~400 mil) em várias chamadas, ajustando o tamanho conforme a carga do servidor."
			},
			{
				"id": "query__estouCienteQueEstaChaveUtilizaPostgreSQL18",
				"location": "query",
				"path": [
					"estouCienteQueEstaChaveUtilizaPostgreSQL18"
				],
				"displayName": "Estou Ciente Que Esta Chave Utiliza Postgre SQL18",
				"required": true,
				"type": "string",
				"description": "Confirmação OBRIGATÓRIA de que a chave/cliente usa PostgreSQL 18. Deve ser true para prosseguir; com false a operação é cancelada."
			},
			{
				"id": "query__tamanhoLote",
				"location": "query",
				"path": [
					"tamanhoLote"
				],
				"displayName": "Tamanho Lote",
				"required": false,
				"type": "string",
				"description": "Quantidade de clientes por transação (lote/commit). Se não informado, usa o padrão 10000. Diferente de qtExcluir, que limita o TOTAL da chamada."
			},
			{
				"id": "query__confirmoExclusaoTotalClientesDaEmpresa",
				"location": "query",
				"path": [
					"confirmoExclusaoTotalClientesDaEmpresa"
				],
				"displayName": "Confirmo Exclusao Total Clientes Da Empresa",
				"required": false,
				"type": "string",
				"description": "Confirmação de segurança contra exclusão em massa acidental. Só é exigida quando os clientes a excluir passam de 50% da base do Treino (ex.: leitura do ZW vazia/anômala). Nesse caso, deve ser true para prosseguir."
			}
		],
