export const PACTO_OPERATIONS: PactoOperationDefinition[] = [...PACTO_OPERATIONS_PART_0, ...PACTO_OPERATIONS_PART_1, ...PACTO_OPERATIONS_PART_2, ...PACTO_OPERATIONS_PART_3, ...PACTO_OPERATIONS_PART_4, ...PACTO_OPERATIONS_PART_5, ...PACTO_OPERATIONS_PART_6, ...PACTO_OPERATIONS_PART_7, ...PACTO_OPERATIONS_PART_8, ...PACTO_OPERATIONS_PART_9];

const operationByKey = new Map(
	PACTO_OPERATIONS.map((operation) => [`${operation.area}:${operation.key}`, operation]),
);

export function getPactoOperation(area: string, key: string): PactoOperationDefinition | undefined {
	return operationByKey.get(`${area}:${key}`);
}
